# function to get row stats

def row_stats(y):
    rmin=999; rmax=-1; gmin=999; gmax=-1; bmin=999; bmax=-1
    for x in range(w):
        i=(y*w+x)*3
        r=nums[i]; g=nums[i+1]; b=nums[i+2]
        if r<rmin: rmin=r
        if r>rmax: rmax=r
        if g<gmin: gmin=g
        if g>gmax: gmax=g
        if b<bmin: bmin=b
        if b>bmax: bmax=b
    return (rmin,rmax,gmin,gmax,bmin,bmax)

